#include <print>

int main() {
    for (int i = 1; i <= 9; i++) {
        for (int j = 1; j <= 9; j++) {
            std::print("{}×{}={}  ", j, i, i * j);
        }
        std::println("");
    }

    for (int i = 1; i <= 5; i++) {
        for (int j = 1; j <= i; j++) {
            std::print("*");
        }
        std::println("");
    }

    return 0;
}

